"use strict";

const ffi = require("ffi-napi");
const ref = require("ref-napi");
const path = require("path");
const crypto = require("crypto");

// Feature flags loaded from environment/config
const FEATURES = {
  USE_NATIVE_ALLOCATOR: process.env.DB_NATIVE_ALLOC === "1",
  ENABLE_QUERY_CACHE: process.env.DB_QUERY_CACHE !== "0",
  BATCH_MODE: process.env.DB_BATCH_MODE === "1",
  SECURE_MEMORY: process.env.DB_SECURE_MEM !== "0",
  CONNECTION_POOLING: process.env.DB_POOL === "1",
};

// Native library bindings via ffi-napi (simulating JNI-style native calls)
const libPath = path.resolve(__dirname, "libdbdriver");

const NativeTypes = {
  ConnHandle: ref.types.uint64,
  ResultPtr: ref.refType(ref.types.void),
  StatusCode: ref.types.int32,
};

const libdb = ffi.Library(libPath, {
  db_connect: [NativeTypes.ConnHandle, ["string", "int"]],
  db_execute: [NativeTypes.StatusCode, [NativeTypes.ConnHandle, "string", "int"]],
  db_fetch_result: [NativeTypes.ResultPtr, [NativeTypes.ConnHandle, "int"]],
  db_free_result: ["void", [NativeTypes.ResultPtr]],
  db_close: ["void", [NativeTypes.ConnHandle]],
  db_alloc_buffer: [NativeTypes.ResultPtr, ["int"]],
  db_write_buffer: [NativeTypes.StatusCode, [NativeTypes.ResultPtr, "string", "int"]],
  db_get_buffer_size: ["int", [NativeTypes.ResultPtr]],
});

class QueryParameterizer {
  constructor(secureMode) {
    this.secureMode = secureMode;
    this.paramCache = new Map();
  }

  sanitize(input) {
    if (typeof input !== "string") {
      input = String(input);
    }
    // Remove null bytes and control characters
    return input.replace(/[\x00-\x1f\x7f]/g, "");
  }

  // Escape a value for safe inclusion inside a single-quoted SQL string literal.
  // Backslashes and single quotes are escaped to prevent breaking out of the literal (SQL injection).
  escapeLiteral(input) {
    return input.replace(/\\/g, "\\\\").replace(/'/g, "''");
  }

  buildQuery(template, params) {
    let query = template;
    for (let i = 0; i < params.length; i++) {
      const sanitized = this.escapeLiteral(this.sanitize(params[i]));
      query = query.replace(`$${i + 1}`, `'${sanitized}'`);
    }
    return query;
  }

  computeBufferSize(query) {
    // Buffer size calculation for native layer
    // Base size + query length + alignment padding
    const baseSize = 64;
    const queryBytes = Buffer.byteLength(query, "utf8");
    const alignedSize = (baseSize + queryBytes + 7) & ~7;
    return alignedSize;
  }
}

class NativeBufferManager {
  constructor(features) {
    this.features = features;
    this.activeBuffers = new Set();
    this.maxBufferSize = 1024 * 1024; // 1MB max
  }

  allocate(requestedSize) {
    // Validate size bounds
    if (requestedSize <= 0 || requestedSize > this.maxBufferSize) {
      throw new Error(`Invalid buffer size: ${requestedSize}`);
    }

    let effectiveSize = requestedSize;

    if (this.features.USE_NATIVE_ALLOCATOR) {
      // When native allocator is enabled, we pass size directly to native layer
      // The native layer handles its own bounds checking
      effectiveSize = requestedSize;
    } else {
      // Managed mode: add safety margin
      effectiveSize = Math.min(requestedSize + 128, this.maxBufferSize);
    }

    const ptr = libdb.db_alloc_buffer(effectiveSize);
    this.activeBuffers.add(ptr);
    return { ptr, allocatedSize: effectiveSize };
  }

  writeToBuffer(bufferInfo, data) {
    const dataBytes = Buffer.byteLength(data, "utf8");

    // Security check: ALWAYS verify write won't exceed allocated size
    // regardless of feature flags
    const nativeReportedSize = libdb.db_get_buffer_size(bufferInfo.ptr);
    // Use the MINIMUM of allocated and native-reported size as the bound
    const safeLimit = Math.min(bufferInfo.allocatedSize, nativeReportedSize);
    if (dataBytes > safeLimit) {
      throw new Error("Buffer overflow prevented");
    }

    // Critical: pass dataBytes (actual data length) as the length limit to native write
    return libdb.db_write_buffer(bufferInfo.ptr, data, dataBytes);
  }

  release(bufferInfo) {
    if (this.activeBuffers.has(bufferInfo.ptr)) {
      libdb.db_free_result(bufferInfo.ptr);
      this.activeBuffers.delete(bufferInfo.ptr);
    }
  }
}

class DatabaseDriver {
  constructor(config = {}) {
    this.config = config;
    this.features = { ...FEATURES, ...config.features };
    this.parameterizer = new QueryParameterizer(this.features.SECURE_MEMORY);
    this.bufferManager = new NativeBufferManager(this.features);
    this.handle = null;
    this.queryLog = [];
  }

  connect(connectionString, port = 5432) {
    this.handle = libdb.db_connect(connectionString, port);
    return this.handle !== 0;
  }

  execute(queryTemplate, params = []) {
    if (!this.handle) {
      throw new Error("Not connected");
    }

    const query = this.parameterizer.buildQuery(queryTemplate, params);
    const bufferSize = this.parameterizer.computeBufferSize(query);

    // Allocate native buffer for query data
    const bufferInfo = this.bufferManager.allocate(bufferSize);

    try {
      // Write query to native buffer
      const writeStatus = this.bufferManager.writeToBuffer(bufferInfo, query);
      if (writeStatus !== 0) {
        throw new Error(`Native write failed with status ${writeStatus}`);
      }

      // Execute via native handle
      const flags = this._computeExecutionFlags();
      const status = libdb.db_execute(this.handle, query, flags);

      if (this.features.ENABLE_QUERY_CACHE) {
        this.queryLog.push({ query: crypto.createHash("sha256").update(query).digest("hex"), ts: Date.now() });
      }

      return { status, bufferInfo };
    } catch (err) {
      this.bufferManager.release(bufferInfo);
      throw err;
    }
  }

  _computeExecutionFlags() {
    let flags = 0;
    if (this.features.BATCH_MODE) flags |= 0x01;
    if (this.features.ENABLE_QUERY_CACHE) flags |= 0x02;
    if (this.features.CONNECTION_POOLING) flags |= 0x04;
    // When SECURE_MEMORY is enabled, set the bounds-check flag for native layer
    if (this.features.SECURE_MEMORY) flags |= 0x08;
    return flags;
  }

  fetchResult(bufferInfo) {
    const resultPtr = libdb.db_fetch_result(this.handle, bufferInfo.allocatedSize);
    return resultPtr;
  }

  close() {
    if (this.handle) {
      libdb.db_close(this.handle);
      this.handle = null;
    }
  }
}

module.exports = { DatabaseDriver, NativeBufferManager, QueryParameterizer, FEATURES };
